import{_ as a,o as c,c as o,a2 as t}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"中文控制台层","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/chinese-layer.md","filePath":"zh/arch/chinese-layer.md"}'),d={name:"zh/arch/chinese-layer.md"};function i(n,e,r,l,s,h){return c(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="中文控制台层" tabindex="-1">中文控制台层 <a class="header-anchor" href="#中文控制台层" aria-label="Permalink to &quot;中文控制台层&quot;">​</a></h1><p><code>chinese/</code> 渲染 CJK 用户内容，而系统自身的字符串保持 ASCII：</p><h2 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h2><ul><li><code>chinese_font_data.c</code> - 16x16 位图字形</li><li><code>encoding.c</code> - gb2312 / utf-8 / ascii 编解码器（已测试往返转换）</li><li><code>console_cn.c</code> - 帧缓冲上的 CJK 控制台行</li><li><code>render_cn.c</code> - 字形光栅流水线</li><li><code>pinyin_data.c</code> + 输入法 - 音节解析、交互式行</li><li><code>tui_cn_*.c</code> - 中文硬件/网络/系统信息 TUI 应用</li></ul><h2 id="双系统并存原理" tabindex="-1">双系统并存原理 <a class="header-anchor" href="#双系统并存原理" aria-label="Permalink to &quot;双系统并存原理&quot;">​</a></h2><p>ASCII 契约针对的是<em>系统</em>字符串（提示符、命令名、帮助、启动消息）- 硬件终端兼容性。当该层激活时，用户内容（文件名、文件体、编辑器缓冲区）通过编解码器流转，并在 CJK 字体上渲染。若设置 <code>CONFIG_CHINESE=n</code>，控制台将路由至 <code>screen_console</code> 中的 ASCII 等效实现 - 真实代码，两条路径，一个契约。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p><code>chinesetest</code>（完整回归测试）、<code>encoding-test</code>（编解码器往返转换）、<code>font-test</code>（混合行渲染）、<code>ime-test</code>（音节解析）。</p>',8)])])}const u=a(d,[["render",i]]);export{p as __pageData,u as default};
